const item = $input.first().json.body || $input.first().json;
const prompt = "You are an autonomous AI specialist for Mana Community Platform operations: Real-time kitchen order preparation delay detector and delivery partner synchronizer. Evaluates order item complexity, current kitchen active orders, and rider ETA to forecast prep delays and draft polite customer status updates.

Analyze the following input payload securely:
__DATA__

Respond strictly with valid JSON conforming to this schema:
{"orderId":"ORD-9421","restaurantName":"Dosa Express","kitchenStatus":"BOTTLENECK_DETECTED","delayMinutes":12,"originalEta":"20:30","revisedEta":"20:42","bottleneckReason":"Peak dinner hour surge with 8 tandoor orders in parallel.","mitigationActions":["Prioritize packaging of cold sides","Stagger delivery rider dispatch by 10 minutes"],"customerUpdateMessage":"Namaste! Your order at Dosa Express is being prepared fresh. Due to a small rush, our chef needs 12 extra minutes to guarantee quality. Revised arrival: 20:42. Thank you for your patience!"}

Rules:
- Return pure JSON only, no markdown wrapping, no extra keys.
- Never expose PII or confidential tenant data.
- Ensure realistic domain heuristics.";
return [{ json: { prompt: prompt.replace("__DATA__", JSON.stringify(item, null, 2)), originalInput: item } }];

const inputData = $input.first().json;
try {
  const text = inputData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("No Gemini output text");
  const parsed = JSON.parse(text);
  return [{ json: { status: "success", auditedAt: new Date().toISOString(), ...parsed } }];
} catch (e) {
  return [{ json: { status: "fallback", error: e.message, auditedAt: new Date().toISOString(), ...{"orderId":"ORD-9421","restaurantName":"Dosa Express","kitchenStatus":"BOTTLENECK_DETECTED","delayMinutes":12,"originalEta":"20:30","revisedEta":"20:42","bottleneckReason":"Peak dinner hour surge with 8 tandoor orders in parallel.","mitigationActions":["Prioritize packaging of cold sides","Stagger delivery rider dispatch by 10 minutes"],"customerUpdateMessage":"Namaste! Your order at Dosa Express is being prepared fresh. Due to a small rush, our chef needs 12 extra minutes to guarantee quality. Revised arrival: 20:42. Thank you for your patience!"} } }];
}
